// Package cimddemo carries the static fixtures of the CIMD example clients
// (draft-ietf-oauth-client-id-metadata-document): the Client ID Metadata
// Documents served for the https://cimd.example.org/client and
// https://agent.example.org/ai-agent identifiers and the fixed signing seeds
// they reference, so the example authorization server and the demo clients
// (cimdclient, agentclient) agree without external infrastructure. The
// documents are resolved through the real cimd.Resolver path; only the
// transport is in-memory because the hardened httpfetch refuses loopback
// destinations by SSRF pre-flight.
package cimddemo

import (
	"context"

	"zntr.io/solid/sdk/cimd"
	"zntr.io/solid/server/storage"
)

